import * as React from "react";
import {
  PlasmicEditStaffs,
  DefaultEditStaffsProps
} from "./plasmic/sayban/PlasmicEditStaffs";
import { HTMLElementRefOf } from "@plasmicapp/react-web";
import {
  parseStaffNoCriminalRecord,
  setStaffNoCriminalRecord
} from "./staff/staffClearanceStore";
import styles from "./EditStaffs.module.css";

export interface EditStaffsProps extends DefaultEditStaffsProps {}

function EditStaffs_(props: EditStaffsProps, ref: HTMLElementRefOf<"div">) {
  const data = (props as { data?: Record<string, unknown> }).data;
  const [noCriminalRecord, setNoCriminalRecord] = React.useState(() =>
    parseStaffNoCriminalRecord(data?.no_criminal_record)
  );

  React.useEffect(() => {
    const next = parseStaffNoCriminalRecord(data?.no_criminal_record);
    setNoCriminalRecord(next);
    setStaffNoCriminalRecord(next);
  }, [data?.id, data?.no_criminal_record]);

  React.useEffect(() => {
    setStaffNoCriminalRecord(noCriminalRecord);
  }, [noCriminalRecord]);

  return (
    <PlasmicEditStaffs
      root={{ ref }}
      {...props}
      overrides={{
        experienceYears: {
          wrap: node => (
            <>
              {node}
              <label className={styles.switchRow}>
                <span className={styles.label}>عدم سوءپیشینه</span>
                <input
                  type="checkbox"
                  className={styles.checkbox}
                  checked={noCriminalRecord}
                  onChange={e => setNoCriminalRecord(e.target.checked)}
                  aria-label="عدم سوءپیشینه"
                />
              </label>
            </>
          )
        }
      }}
    />
  );
}

const EditStaffs = React.forwardRef(EditStaffs_);
export default EditStaffs;
